/* GitHub Theme - Official GitHub brand colors (Primer Design System)  */

/* Light mode */
[data-theme="github-light"] {
  --background: #ffffff;
  --foreground: #1c2229;
  --card: #f7f9fa;
  --card-foreground: #1c2229;
  --popover: #ffffff;
  --popover-foreground: #1c2229;
  --primary: #107823;
  --primary-foreground: #ffffff;
  --secondary: #eff2f5;
  --secondary-foreground: #282f35;
  --muted: #f4f5f7;
  --muted-foreground: #5d646c;
  --accent: #3072df;
  --accent-foreground: #ffffff;
  --destructive: #cc272e;
  --destructive-foreground: #ffffff;
  --border: #d0d5d9;
  --input: #f4f5f7;
  --ring: #3072df;
  --chart-1: #107823;
  --chart-2: #3072df;
  --chart-3: #b76ec7;
  --chart-4: #dd8364;
  --chart-5: #009583;
  --radius: 0.375rem;
  --sidebar: #f4f5f7;
  --sidebar-foreground: #1c2229;
  --sidebar-primary: #107823;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #eff2f5;
  --sidebar-accent-foreground: #282f35;
  --sidebar-border: #d0d5d9;
  --sidebar-ring: #3072df;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  --shadow-color: #29313d;
  --shadow-opacity: 0.06;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 0 0px hsl(215 20% 20% / 0.04);
  --shadow-xs: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 1px 3px 0px hsl(215 20% 20% / 0.06);
  --shadow-sm: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
  --shadow: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
  --shadow-md: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 4px 8px 0px hsl(215 20% 20% / 0.1);
  --shadow-lg: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 8px 16px 0px hsl(215 20% 20% / 0.1);
  --shadow-xl: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 12px 28px 0px hsl(215 20% 20% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(215 20% 20% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #0D1117 is GitHub's signature dark background */
[data-theme="github-dark"] {
  --background: #080c10;
  --foreground: #c9ced4;
  --card: #0e1217;
  --card-foreground: #c9ced4;
  --popover: #12171b;
  --popover-foreground: #c9ced4;
  --primary: #278733;
  --primary-foreground: #ffffff;
  --secondary: #161b20;
  --secondary-foreground: #b9bec4;
  --muted: #13161a;
  --muted-foreground: #757b81;
  --accent: #3072df;
  --accent-foreground: #ffffff;
  --destructive: #d74745;
  --destructive-foreground: #ffffff;
  --border: #2a2e33;
  --input: #0e1217;
  --ring: #3072df;
  --chart-1: #278733;
  --chart-2: #3072df;
  --chart-3: #c480d4;
  --chart-4: #ee9373;
  --chart-5: #00a692;
  --radius: 0.375rem;
  --sidebar: #05080b;
  --sidebar-foreground: #c9ced4;
  --sidebar-primary: #278733;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #161b20;
  --sidebar-accent-foreground: #b9bec4;
  --sidebar-border: #2a2e33;
  --sidebar-ring: #3072df;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.4;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 0 0 1px hsl(0 0% 0% / 0.3);
  --shadow-xs: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 1px 3px 0px hsl(0 0% 0% / 0.3);
  --shadow-sm: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
  --shadow: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
  --shadow-md: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 4px 8px 0px hsl(0 0% 0% / 0.4);
  --shadow-lg: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 8px 16px 0px hsl(0 0% 0% / 0.4);
  --shadow-xl: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 12px 28px 0px hsl(0 0% 0% / 0.5);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
}
